-- Expansion; close DML and wrap generators only after compatible server deploy.
create schema sequence_security_private;
revoke all on schema sequence_security_private from public,anon,authenticated,service_role;
grant usage on schema sequence_security_private to authenticated;
create table sequence_security_private.contexts(id bigint generated always as identity primary key,backend_pid integer not null,transaction_id bigint not null,kind text not null);
alter table sequence_security_private.contexts enable row level security;
create policy internal_owner on sequence_security_private.contexts for all to postgres using(true)with check(true);
revoke all on sequence_security_private.contexts from public,anon,authenticated,service_role;
create function sequence_security_private.enter(k text)returns bigint language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare cid bigint;begin insert into sequence_security_private.contexts(backend_pid,transaction_id,kind)values(pg_backend_pid(),txid_current(),k)returning id into cid;return cid;end$$;
create function sequence_security_private.has_context(k text)returns boolean language sql volatile security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from sequence_security_private.contexts c where c.backend_pid=pg_backend_pid()and c.transaction_id=txid_current()and c.kind=k)$$;
create function sequence_security_private.actor()returns bigint language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select access_admin_private.actor()$$;
create function sequence_security_private.allowed(a text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 perform sequence_security_private.actor();if a is null or a not in('view','create','edit','delete')then return false;end if;
 return(a='view'and(public.app_is_admin()or exists(select 1 from role_access_matrix where role_id=public.app_active_role_id()and resource_key='legacy:all'and can_view)))or exists(select 1 from role_access_matrix m where m.role_id=public.app_active_role_id()and m.resource_key='core:number-sequences'and m.can_view and case a when'view'then true when'create'then m.can_create when'edit'then m.can_edit else m.can_delete end);
 exception when insufficient_privilege then return false;end$$;
create function sequence_security_private.access(a text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare u bigint:=sequence_security_private.actor();begin if not sequence_security_private.allowed(a)then raise exception using errcode='42501',message='Requiere permiso explicito de secuencias.';end if;return u;end$$;
create function sequence_security_private.member(sid bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from subsidiaries s join user_subsidiaries u using(subsidiary_id)where s.subsidiary_id=sid and s.is_active and u.user_id=public.app_user_id())$$;
create function sequence_security_private.visible(r public.number_sequences)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin return sequence_security_private.allowed('view')and(r.entity_key is not null or sequence_security_private.member(r.subsidiary_id));end$$;
create function sequence_security_private.used(r public.number_sequences)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select r.entity_key is not null or r.current_number>0 or exists(select 1 from public."transaction" t where t.transaction_type_id=r.transaction_type_id and t.subsidiary_id=r.subsidiary_id)or exists(select 1 from public.journal j where j.subsidiary_id=r.subsidiary_id and starts_with(j.journal_number,coalesce(r.prefix,''))and right(j.journal_number,length(coalesce(r.suffix,'')))=coalesce(r.suffix,''))$$;
create function sequence_security_private.dto(r public.number_sequences)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$
declare immutable text[]:=array['scope_type','entity_key','transaction_type_id','subsidiary_id'];used boolean:=sequence_security_private.used(r);editable boolean:=r.entity_key is null and sequence_security_private.member(r.subsidiary_id);begin
 if used then immutable:=immutable||array['prefix','suffix','padding_length'];end if;if not r.allow_manual_update then immutable:=immutable||array['current_number','allow_manual_update'];end if;
 return jsonb_build_object('sequence_id',r.sequence_id,'scope_type',r.scope_type,'entity_key',r.entity_key,'transaction_type_id',r.transaction_type_id,'subsidiary_id',r.subsidiary_id,'prefix',r.prefix,'suffix',r.suffix,'current_number',r.current_number::text,'padding_length',r.padding_length,'allow_manual_update',r.allow_manual_update,'_revision',md5(to_jsonb(r)::text),'_immutable',immutable,'_actions',jsonb_build_object('canEdit',editable and sequence_security_private.allowed('edit'),'canDelete',editable and not used and sequence_security_private.allowed('delete')));
end$$;
create function public.number_sequence_catalog()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform sequence_security_private.access('view');return(select coalesce(jsonb_agg(sequence_security_private.dto(r)order by r.sequence_id),'[]'::jsonb)from number_sequences r where sequence_security_private.visible(r));end$$;
create function public.number_sequence_access()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform sequence_security_private.access('view');return jsonb_build_object('canView',true,'canCreate',sequence_security_private.allowed('create'),'canEdit',sequence_security_private.allowed('edit'),'canDelete',sequence_security_private.allowed('delete'),'references',jsonb_build_object('organization/subsidiaries',(select coalesce(jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name)order by s.name),'[]')from subsidiaries s where sequence_security_private.member(s.subsidiary_id)),'core/transaction-types',(select coalesce(jsonb_agg(jsonb_build_object('transaction_type_id',transaction_type_id,'name',name,'abbreviation',abbreviation)order by name),'[]')from transaction_types where abbreviation not in('FAC_PRO','NC_PRO','ND_PRO'))));end$$;
create function public.save_number_sequence(p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare old_r public.number_sequences;r public.number_sequences;merged jsonb;sid bigint;tt bigint;counter numeric;padding numeric;pre text;suf text;manual boolean;cid bigint;begin
 perform sequence_security_private.access(case when p_id is null then'create'else'edit'end);
 if jsonb_typeof(p_payload)is distinct from'object'or pg_column_size(p_payload)>64000 or exists(select 1 from jsonb_object_keys(p_payload)k where k not in('scope_type','entity_key','transaction_type_id','subsidiary_id','prefix','suffix','current_number','padding_length','allow_manual_update','_revision'))then raise exception using errcode='22023',message='Campos de secuencia invalidos.';end if;
 -- Serialize by transaction type before row locks, matching the generator.
 if p_id is not null then select *into old_r from number_sequences where sequence_id=p_id;if not found or old_r.entity_key is not null or not sequence_security_private.member(old_r.subsidiary_id)then raise exception using errcode='42501',message='Secuencia no autorizada.';end if;tt:=old_r.transaction_type_id;
 else begin tt:=nullif(p_payload->>'transaction_type_id','')::bigint;exception when invalid_text_representation or numeric_value_out_of_range then raise exception using errcode='22023',message='Tipo invalido.';end;end if;
 if tt is null then raise exception using errcode='22023',message='Tipo obligatorio.';end if;
 perform pg_advisory_xact_lock(hashtextextended('transaction-number:'||tt::text,0));
 if p_id is not null then select *into old_r from number_sequences where sequence_id=p_id for update;if not found then raise exception using errcode='42501',message='Secuencia no autorizada.';end if;if p_payload->>'_revision'is null or p_payload->>'_revision'is distinct from md5(to_jsonb(old_r)::text)then raise exception using errcode='55000',message='La secuencia cambio. Consulte nuevamente.';end if;end if;
 merged:=case when p_id is null then jsonb_build_object('scope_type','Transacción','current_number',0,'padding_length',8,'allow_manual_update',false)else to_jsonb(old_r)end||p_payload;
 if merged->>'scope_type'is distinct from'Transacción'or nullif(merged->>'entity_key','')is not null then raise exception using errcode='22023',message='Las entidades se numeran mediante secuencias nativas y son de solo lectura.';end if;
 begin sid:=(merged->>'subsidiary_id')::bigint;tt:=(merged->>'transaction_type_id')::bigint;exception when invalid_text_representation or numeric_value_out_of_range then raise exception using errcode='22023',message='Origen invalido.';end;
 if sid is null or tt is null or not sequence_security_private.member(sid)then raise exception using errcode='42501',message='Filial no autorizada.';end if;
 if not exists(select 1 from transaction_types where transaction_type_id=tt and abbreviation not in('FAC_PRO','NC_PRO','ND_PRO'))then raise exception using errcode='22023',message='Tipo no numerado internamente.';end if;
 if p_id is not null and row(tt,sid)is distinct from row(old_r.transaction_type_id,old_r.subsidiary_id)then raise exception using errcode='55000',message='El origen de la secuencia es inmutable.';end if;
 if coalesce(merged->>'current_number','')!~'^[0-9]{1,19}$'or coalesce(merged->>'padding_length','')!~'^[0-9]{1,2}$'or jsonb_typeof(merged->'allow_manual_update')is distinct from'boolean'or exists(select 1 from jsonb_each(p_payload)e where e.key in('prefix','suffix')and jsonb_typeof(e.value)not in('string','null'))then raise exception using errcode='22023',message='Contador, formato o bloqueo invalidos.';end if;
 counter:=(merged->>'current_number')::numeric;padding:=(merged->>'padding_length')::numeric;manual:=(merged->>'allow_manual_update')::boolean;pre:=nullif(merged->>'prefix','');suf:=nullif(merged->>'suffix','');
 if counter>9223372036854775806 or(jsonb_typeof(p_payload->'current_number')='number'and counter>9007199254740991)or padding not between 1 and 20 or length(coalesce(pre,''))>30 or length(coalesce(suf,''))>30 or coalesce(pre,'')~'[<>[:cntrl:]]'or coalesce(suf,'')~'[<>[:cntrl:]]'then raise exception using errcode='22023',message='Valores de secuencia invalidos.';end if;
 if p_id is not null then
  if counter<old_r.current_number or(not old_r.allow_manual_update and(counter<>old_r.current_number or manual))then raise exception using errcode='55000',message='El contador no retrocede ni se desbloquea.';end if;
  if sequence_security_private.used(old_r)and row(pre,suf,padding)is distinct from row(old_r.prefix,old_r.suffix,old_r.padding_length::numeric)then raise exception using errcode='55000',message='La secuencia utilizada conserva su formato.';end if;
 elsif counter<>0 and not manual then raise exception using errcode='22023',message='El contador inicial bloqueado debe ser cero.';end if;
 cid:=sequence_security_private.enter('maintenance');
 if p_id is null then insert into number_sequences(scope_type,entity_key,transaction_type_id,subsidiary_id,prefix,suffix,current_number,padding_length,allow_manual_update)values('Transacción',null,tt,sid,pre,suf,counter,padding,manual)returning *into r;
 else update number_sequences set prefix=pre,suffix=suf,current_number=counter,padding_length=padding,allow_manual_update=manual where sequence_id=p_id returning *into r;end if;
 delete from sequence_security_private.contexts where id=cid;return sequence_security_private.dto(r);
end$$;
create function public.delete_number_sequence(p_id bigint,p_revision text)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.number_sequences;cid bigint;begin
 perform sequence_security_private.access('delete');select *into r from number_sequences where sequence_id=p_id;if not found or r.entity_key is not null or not sequence_security_private.member(r.subsidiary_id)then raise exception using errcode='42501',message='Secuencia no autorizada.';end if;
 perform pg_advisory_xact_lock(hashtextextended('transaction-number:'||r.transaction_type_id::text,0));select *into r from number_sequences where sequence_id=p_id for update;
 if not found or p_revision is null or p_revision is distinct from md5(to_jsonb(r)::text)or sequence_security_private.used(r)then raise exception using errcode='55000',message='La secuencia cambio o ya fue utilizada.';end if;
 cid:=sequence_security_private.enter('maintenance');delete from number_sequences where sequence_id=p_id;delete from sequence_security_private.contexts where id=cid;return true;end$$;
revoke all on all functions in schema sequence_security_private from public,anon,authenticated,service_role;
grant execute on function sequence_security_private.visible(public.number_sequences)to authenticated;
revoke all on function public.number_sequence_catalog(),public.number_sequence_access(),public.save_number_sequence(jsonb,bigint),public.delete_number_sequence(bigint,text)from public,anon,authenticated,service_role;
grant execute on function public.number_sequence_catalog(),public.number_sequence_access(),public.save_number_sequence(jsonb,bigint),public.delete_number_sequence(bigint,text)to authenticated;
notify pgrst,'reload schema';
